import {Link} from '@github-ui/react-core/link'
import {usePreloadRoute} from '@github-ui/react-router'
import {Button, Flash} from '@primer/react'
import {useState} from 'react'

import {FooterLinks} from '../components/FooterLinks'
import {reactSandboxFutureIdRoute} from './id-route'

export function Preload() {
  const preload = usePreloadRoute()
  const [preloaded, setPreloaded] = useState(false)
  const targetUrl = reactSandboxFutureIdRoute.generatePath({id: '1'})

  return (
    <>
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h2 data-hpc>Preload Demo</h2>
      <p>
        Click the button below to preload <code>/_react_sandbox_future/1</code>. Then navigate to see the data load
        instantly.
      </p>

      <Button
        onClick={() => {
          const matched = preload(targetUrl)
          if (matched) setPreloaded(true)
        }}
      >
        Preload /_react_sandbox_future/1
      </Button>

      <div role="status">
        {preloaded && (
          <Flash className="tmp-mt-3">
            Preload triggered!{' '}
            <Link to={targetUrl} className="Link--inTextBlock">
              Navigate to /_react_sandbox_future/1
            </Link>{' '}
            — data should load instantly.
          </Flash>
        )}
      </div>

      <Link to="/_react_sandbox_future/2" preload="intent">
        Intent Preload Link to /_react_sandbox_future/2
      </Link>

      <FooterLinks />
    </>
  )
}
